<template>
  <div class="tarot-page page-transition"><section class="tarot-card-a glass-card">
    <header class="tarot-header"><span>RITUAL OF INSIGHT</span><h2>塔罗占卜</h2><p>洗牌、凭直觉选牌，让答案逐一显现。</p></header>
    <div class="spread-options"><button v-for="s in spreads" :key="s.key" class="spread-btn" :class="{ active: selectedSpread === s.key }" :disabled="busy" @click="selectSpread(s.key)"><b>{{ s.name }}</b><small>{{ s.desc }}</small></button></div>
    <div v-if="phase === 'idle'" class="ritual-intro"><div class="deck-stack" @click="shuffle"><i></i><i></i><div class="deck-face"><span>✦</span><strong>点击洗牌</strong></div></div><p>{{ currentSpread.desc }} · 需要抽取 {{ positions.length }} 张</p></div>
    <div v-else-if="phase === 'shuffling'" class="shuffle-stage"><div v-for="i in 8" :key="i" class="orbit-card" :style="{ '--i': i }">✦</div><p>正在洗牌，请专注于你的问题…</p></div>
    <div v-else class="reading-stage"><div v-if="phase === 'choosing'" class="choose-guide">请从星轨中凭直觉选择第 {{ chosenCount + 1 }} 张牌</div><div class="card-ribbon" :class="{ choosing: phase === 'choosing' }"><button v-for="(card, index) in cards" :key="index" class="pick-card" :class="{ selected: card.revealed }" :disabled="phase !== 'choosing' || card.revealed" @click="chooseCard(index)">✦</button></div><div class="spread-board" :class="'layout-' + selectedSpread"><article v-for="(card, index) in cards" :key="'slot-' + index" class="spread-slot"><span class="slot-number">{{ index + 1 }}</span><small>{{ positions[index] }}</small><div class="tarot-card" :class="{ reveal: card.revealed, reversed: card.isReversed }"><div class="card-inner"><div class="card-back">✦</div><div class="card-front"><span class="emblem">{{ card.emblem }}</span><b>{{ card.isReversed ? '逆位 · ' : '正位 · ' }}{{ card.name }}</b><small>{{ card.nameEn }}</small></div></div></div></article></div></div>
    <section v-if="allFlipped" class="reading-meanings"><h3>牌面私语</h3><article v-for="(c, i) in cards" :key="'meaning-' + i"><b>{{ positions[i] }} · {{ c.name }}</b><p>{{ c.meaning }}</p></article><button v-if="!interpretation && !interpreting" class="interpret-btn" @click="interpret">获取 AI 综合解读</button><div v-if="interpreting || interpretation" class="ai-reading"><b>✦ 塔罗师解读</b><MarkdownRender v-if="interpretation" :content="interpretation" /><p v-else>正在聆听牌面的讯息…</p></div></section>
    <button v-if="phase !== 'idle'" class="reset-btn" @click="reset">重新开始</button>
  </section><Transition name="toast-fade"><div v-if="toast" class="toast-bar">{{ toast }}</div></Transition></div>
</template>
<script setup lang="ts">
import { computed, onBeforeUnmount, ref } from "vue"
import { drawTarotCardsWS, interpretTarotWS, type TarotDrawnCard, type TarotSpread } from "@/api"
import MarkdownRender from "@/components/MarkdownRender.vue"
interface Card extends TarotDrawnCard { revealed: boolean }
const spreads: { key: TarotSpread; name: string; desc: string; positions: string[] }[] = [
  { key: "daily", name: "每日一牌", desc: "一句指引，照见今天", positions: ["今日指引"] }, { key: "three_card", name: "时间之流", desc: "过去、现在与未来", positions: ["过去", "现在", "未来"] }, { key: "relationship", name: "关系镜像", desc: "看见彼此与关系", positions: ["你自己", "对方", "关系核心"] }, { key: "decision", name: "二择一", desc: "比较两条行动路径", positions: ["当下核心", "选项 A", "A 的走向", "选项 B", "B 的走向"] }, { key: "celtic_cross", name: "凯尔特十字", desc: "十张牌全景式梳理", positions: ["现状", "挑战", "显意识", "潜意识", "过去", "近期未来", "你的状态", "环境影响", "希望与担忧", "结果趋势"] },
]
const selectedSpread = ref<TarotSpread>("daily"), phase = ref<"idle" | "shuffling" | "choosing" | "done">("idle"), cards = ref<Card[]>([]), interpretation = ref(""), interpreting = ref(false), toast = ref("")
let drawWs: WebSocket | null = null, interpretWs: WebSocket | null = null
const currentSpread = computed(() => spreads.find(s => s.key === selectedSpread.value)!), positions = computed(() => currentSpread.value.positions), chosenCount = computed(() => cards.value.filter(c => c.revealed).length), allFlipped = computed(() => cards.value.length > 0 && cards.value.every(c => c.revealed)), busy = computed(() => phase.value === "shuffling" || interpreting.value)
function close(ws: WebSocket | null) { if (ws && ws.readyState < WebSocket.CLOSING) ws.close() }
function showToast(message: string) { toast.value = message; setTimeout(() => toast.value = "", 3200) }
function selectSpread(key: TarotSpread) { if (!busy.value) { selectedSpread.value = key; reset() } }
function shuffle() { phase.value = "shuffling"; interpretation.value = ""; close(drawWs); drawWs = drawTarotCardsWS(selectedSpread.value, { onCards(data) { cards.value = data.map(c => ({ ...c, revealed: false })); setTimeout(() => phase.value = "choosing", 850) }, onError(error) { phase.value = "idle"; showToast(`洗牌失败：${error}`) } }) }
function chooseCard(index: number) { if (index !== chosenCount.value) return; cards.value[index].revealed = true; if (chosenCount.value === cards.value.length) phase.value = "done" }
function interpret() { interpreting.value = true; interpretation.value = ""; close(interpretWs); interpretWs = interpretTarotWS({ spread: selectedSpread.value, cards: cards.value }, { onMessage: chunk => interpretation.value += chunk, onDone: () => interpreting.value = false, onError: error => { interpreting.value = false; showToast(`解读失败：${error}`) } }) }
function reset() { close(drawWs); close(interpretWs); phase.value = "idle"; cards.value = []; interpretation.value = ""; interpreting.value = false }
onBeforeUnmount(() => { close(drawWs); close(interpretWs) })
</script>
